import{_ as t,o,c as a,ah as i}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse('{"title":"The Matter with the Money and the Little Dots","description":"","frontmatter":{},"headers":[],"relativePath":"en/logbuch/die-sache-mit-dem-geld.md","filePath":"en/logbuch/die-sache-mit-dem-geld.md"}'),s={name:"en/logbuch/die-sache-mit-dem-geld.md"};function n(r,e,l,h,m,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="the-matter-with-the-money-and-the-little-dots" tabindex="-1">The Matter with the Money and the Little Dots <a class="header-anchor" href="#the-matter-with-the-money-and-the-little-dots" aria-label="Permalink to &quot;The Matter with the Money and the Little Dots&quot;">​</a></h1><p><strong>Theme:</strong> <em>Pointillism as a Financial Strategy.</em></p><p>In our latest brainstorm session, we refined the concept of the <strong>&quot;Pointillism of Capital.&quot;</strong> It&#39;s not just an aesthetic gimmick for the film; it&#39;s a profound analysis of how power works today.</p><ul><li><strong>The Theory:</strong> Large, scandalous sums are eye-catching. Many small, &quot;harmless&quot; tranches create a shimmering surface that conceals the true intention.</li><li><strong>The Application:</strong> We see this in Heidi Horten&#39;s 49,000-euro donations just as much as in Helmut&#39;s systematic acquisitions of smaller stores.</li></ul><p>This will be the visual leitmotif of the film: The camera starts very close to a &quot;dot&quot; (a coin, a signature) and slowly zooms out until the enormous, almost overwhelming picture of the Horten empire becomes visible.</p><p><em>Documented by Volti Sodala &amp; Gemini CLI.</em></p>',6)])])}const p=t(s,[["render",n]]);export{u as __pageData,p as default};
